let control = cx.new(|_| AiMascot::new("Kense").with_status(MascotStatus::Thinking).with_size(24.0).follow_pointer(false));

use gpui::prelude::*;
use kui::components::install_snippet::{InstallCommand, InstallFramework, InstallSnippet, InstallStep};

let steps = vec![InstallStep::new("install", "Install", vec![InstallCommand::new("Cargo", "cargo add kense-kui --rename kui")])];
let control = cx.new(|cx| InstallSnippet::new(vec![InstallFramework::new("rust", "Rust", steps)], cx));

use gpui::prelude::*;
use kui::components::upgrade_prompt::{UpgradePrompt, UpgradePromptOptions};

let control = cx.new(|cx| UpgradePrompt::new(UpgradePromptOptions::default(), cx));

use gpui::{Task, prelude::*};
use kui::components::referral_card::{
    ReferralCard, ReferralCardOptions, ReferralMilestone,
};

let control = cx.new(|cx| {
    ReferralCard::new(
        ReferralCardOptions {
            link: "https://example.com/r/kense20".into(),
            referrals: Some(Vec::new()),
            milestone: ReferralMilestone::new(5, "3 months free"),
            ..Default::default()
        },
        window,
        cx,
    )
    .on_invite(|invite, _, _| {
        // Hand invite.emails and invite.signal to the host's delivery service.
        let _ = invite;
        Task::ready(Ok(()))
    })
});

use gpui::prelude::*;
use kui::components::trial_banner::{CivilDate, TrialBanner, TrialVariant};

let today = CivilDate::new(2026, 10, 27).expect("valid example date");
let ends_at = today.add_days(9);
let control = cx.new(|cx| {
    TrialBanner::new("workspace-trial", cx)
        .with_variant(TrialVariant::Banner)
        .with_schedule(today, ends_at, 9, 14)
});

use gpui::prelude::*;
use kui::components::live_visitors::{
    LivePage, LiveVisitors, LiveVisitorsPaused, LiveVisitorsSnapshot,
};

let control = cx.new(|cx| {
    LiveVisitors::new(cx)
        .with_snapshot(LiveVisitorsSnapshot {
            count: 128,
            pages: vec![LivePage::new("/pricing", 31)],
            ..Default::default()
        })
        .with_paused(false)
});
cx.subscribe(&control, |control, event: &LiveVisitorsPaused, cx| {
    control.update(cx, |control, cx| control.set_paused(event.0, cx));
}).detach();

